import { useMemo } from 'react';
import { bubbleToSvg, type BusinessProcess, type KimballProject, type ThemeName } from '../../core';

/**
 * Renders the exact SVG the exporters produce (one renderer for UI, CLI and
 * downloads). The markup is generated by core with every string escaped.
 */
export function BubbleDiagram({
  project,
  process,
  theme,
  onDimensionClick,
}: {
  project: KimballProject;
  process: BusinessProcess;
  theme: ThemeName;
  onDimensionClick?: (dimensionId: string) => void;
}) {
  const svg = useMemo(() => bubbleToSvg(project, process, { theme, background: false }), [project, process, theme]);
  return (
    <div
      className="diagram"
      onClick={(e) => {
        const g = (e.target as Element).closest('[data-dimension-id]');
        const id = g?.getAttribute('data-dimension-id');
        if (id && onDimensionClick) onDimensionClick(id);
      }}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
